async function ensureAdmin(user){const s=await db.collection('users').doc(user.uid).get();const d=s.exists?s.data():{};return d.role==='admin'||d.isAdmin===true||d.admin===true}
auth.onAuthStateChanged(async user=>{if(!user){$('loginView').classList.remove('hidden');$('app').classList.add('hidden');return}try{if(!(await ensureAdmin(user))){await auth.signOut();$('loginMsg').textContent='Access denied: admin account required.';return}adminUser=user;$('loginView').classList.add('hidden');$('app').classList.remove('hidden');$('adminName').textContent=user.displayName||'Administrator';$('adminEmail').textContent=user.email||'';$('adminAvatar').textContent=(user.displayName||user.email||'A').charAt(0).toUpperCase();$('settingsEmail').textContent=user.email||'—';startLive();loadActivity();loadSettings()}catch(e){await auth.signOut();$('loginMsg').textContent='Could not verify admin access.'}});
