function startLive(){unsubApps?.();unsubReq?.();unsubApps=db.collection('applications').orderBy('createdAt','desc').onSnapshot(s=>{apps=s.docs.map(d=>({id:d.id,...d.data()}));renderAll();$('lastUpdated').textContent='Updated '+new Date().toLocaleTimeString('en-IN')},e=>toast('Applications load error: '+e.message,'error'));unsubReq=db.collection('customerPaymentRequests').orderBy('createdAt','desc').onSnapshot(s=>{requests=s.docs.map(d=>({id:d.id,...d.data()}));renderAll()},e=>toast('Payment requests error: '+e.message,'error'))}
function renderAll(){renderStats();renderRecent();renderApps();renderPayments();renderRequests();}
function renderStats(){const pending=apps.filter(a=>norm(a.status)==='pending').length,under=apps.filter(a=>norm(a.status)==='under process').length,approved=apps.filter(a=>norm(a.status)==='approved').length,rejected=apps.filter(a=>norm(a.status)==='rejected').length,paid=apps.filter(a=>norm(a.paymentStatus)==='paid').length,verify=apps.filter(a=>norm(a.paymentStatus)==='verification_pending').length;const amount=apps.filter(a=>norm(a.paymentStatus)==='paid').reduce((n,a)=>n+Number(a.paymentAmount||190),0);$('statsCards').innerHTML=[['Total Applications',apps.length,'fa-folder-open'],['Pending',pending,'fa-hourglass-half'],['Under Process',under,'fa-arrows-rotate'],['Approved',approved,'fa-circle-check'],['Rejected',rejected,'fa-circle-xmark'],['Payment Pending',verify,'fa-money-bill-transfer'],['Paid Applications',paid,'fa-circle-check'],['Verified Amount','₹'+amount.toLocaleString('en-IN'),'fa-indian-rupee-sign']].map(x=>`<div class="stat"><i class="fa-solid ${x[2]}"></i><div><span>${x[0]}</span><b>${x[1]}</b></div></div>`).join('')}
function renderRecent(){const rows=apps.slice(0,7).map(a=>`<tr><td><b>${esc(a.ackNo)}</b><small>${esc(a.applicationType||'New PAN')}</small></td><td>${esc(a.name||'—')}</td><td>${statusBadge(a.status)}</td><td>${statusBadge(a.paymentStatus||'pending')}</td><td><button class="mini" onclick="viewApp('${a.id}')">View</button> <button class="mini primary" onclick="editApplication('${a.id}')"><i class="fa-solid fa-pen"></i> Edit</button></td></tr>`).join('');$('recentApps').innerHTML=table(['ACK / Type','Applicant','Status','Payment',''],rows);$('recentPayments').innerHTML=apps.filter(a=>norm(a.paymentStatus)==='verification_pending').slice(0,6).map(a=>`<div class="pay-row"><div><b>${esc(a.ackNo)}</b><span>${esc(a.name||'—')} • ₹${Number(a.paymentAmount||190)}</span></div><button class="mini primary" onclick="viewApp('${a.id}')">Review</button></div>`).join('')||'<div class="empty">No payments awaiting verification.</div>'}
function table(head,rows){return `<table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||'<tr><td colspan="9" class="empty">No records found.</td></tr>'}</tbody></table>`}
function renderApps(){const q=norm($('appSearch').value),st=$('appStatus').value,p=$('appPay').value,ty=$('appType').value;const list=apps.filter(a=>(!q||[a.ackNo,a.name,a.phone,a.panNumber,a.email].some(v=>norm(v).includes(q)))&&(st==='all'||norm(a.status)===norm(st))&&(p==='all'||norm(a.paymentStatus)===norm(p))&&(ty==='all'||(a.applicationType||'New PAN')===ty));$('applicationsTable').innerHTML=table(['ACK / Date','Applicant','Mobile','Type','Status','Payment','Amount','Action'],list.map(a=>`<tr><td><b>${esc(a.ackNo)}</b><small>${fmtDate(a.createdAt)}</small></td><td>${esc(a.name||'—')}</td><td>${esc(a.phone||'—')}</td><td>${esc(a.applicationType||'New PAN')}</td><td>${statusBadge(a.status)}</td><td>${statusBadge(a.paymentStatus||'pending')}</td><td>₹${Number(a.paymentAmount||190).toLocaleString('en-IN')}</td><td><button class="mini" onclick="viewApp('${a.id}')">Open</button> <button class="mini primary" onclick="editApplication('${a.id}')"><i class="fa-solid fa-pen"></i> Edit</button></td></tr>`).join(''))}
function renderPayments(){const q=norm($('paySearch').value),f=$('payFilter').value;const list=apps.filter(a=>(f==='all'||norm(a.paymentStatus)===norm(f))&&(!q||[a.ackNo,a.name,a.paymentUtr,a.utr].some(v=>norm(v).includes(q))));$('paymentsTable').innerHTML=table(['ACK','Applicant','Amount','UTR','Payment','Submitted','Action'],list.map(a=>`<tr><td><b>${esc(a.ackNo)}</b></td><td>${esc(a.name||'—')}</td><td>₹${Number(a.paymentAmount||190)}</td><td>${esc(a.paymentUtr||a.utr||'—')}</td><td>${statusBadge(a.paymentStatus||'pending')}</td><td>${fmtDate(a.paymentSubmittedAt||a.customerSubmittedAt)}</td><td><button class="mini primary" onclick="viewApp('${a.id}')">Review</button></td></tr>`).join(''))}
function renderRequests(){const q=norm($('reqSearch').value),f=$('reqFilter').value;const list=requests.filter(r=>(f==='all'||norm(r.status)===norm(f))&&(!q||[r.ackNo,r.name,r.phone,r.id,r.utr].some(v=>norm(v).includes(q))));$('requestsTable').innerHTML=table(['Request','ACK','Customer','Amount','UTR','Status','Created','Action'],list.map(r=>`<tr><td><b>${esc(r.id.slice(0,10))}</b></td><td>${esc(r.ackNo)}</td><td>${esc(r.name||'—')}</td><td>₹${Number(r.amount||190)}</td><td>${esc(r.utr||'—')}</td><td>${statusBadge(r.status)}</td><td>${fmtDate(r.createdAt)}</td><td><button class="mini primary" onclick="viewRequest('${r.id}')">Open</button></td></tr>`).join(''))}
['appSearch','appStatus','appPay','appType','paySearch','payFilter','reqSearch','reqFilter'].forEach(id=>$(id).addEventListener('input',renderAll));
['appStatus','appPay','appType','payFilter','reqFilter'].forEach(id=>$(id).addEventListener('change',renderAll));
async function viewApp(id){const a=apps.find(x=>x.id===id);if(!a)return;logAction('Viewed application',a.ackNo);openModal(`<div class="detail-head"><div><span class="eyebrow">${esc(a.applicationType||'New PAN')}</span><h2>${esc(a.name||'Application')}</h2><p>ACK: <b>${esc(a.ackNo)}</b> • ${fmtDate(a.createdAt)}</p></div><div>${statusBadge(a.status)} ${statusBadge(a.paymentStatus||'pending')}</div></div><div class="detail-actions"><button class="primary" onclick="setAppStatus('${id}','under process')">Under Process</button><button class="success" onclick="setAppStatus('${id}','approved')">Approve</button><button class="danger" onclick="setAppStatus('${id}','rejected')">Reject</button><button onclick="openDocs('${id}')">Documents</button><button onclick="whatsappApp('${id}')">WhatsApp</button></div><div class="detail-grid">${field('ACK Number',a.ackNo)}${field('Applicant',a.name)}${field('Mobile',a.phone)}${field('Email',a.email)}${field('PAN',a.panNumber||'—')}${field('DOB',a.dob)}${field('Gender',a.gender)}${field("Father's Name (First • Middle • Last)",[a.fatherFirstName,a.fatherMiddleName,a.fatherlastName||a.fatherLastName].filter(Boolean).join(' ')||a.father||a.fatherName||'—')}${field("Mother's Name (First • Middle • Last)",[a.motherFirstName,a.motherMiddleName,a.motherlastName||a.motherLastName].filter(Boolean).join(' ')||a.mother||a.motherName||'—')}${field('Address',[a.flatNo,a.villageCity,a.postOffice,a.subDivision,a.district,a.state,a.pinCode].filter(Boolean).join(', '))}${field('Payment Amount','₹'+Number(a.paymentAmount||190))}${field('UTR',a.paymentUtr||a.utr||'—')}${field('Created',fmtDate(a.createdAt))}</div>${a.correctionFields?`<div class="subpanel"><h3>Correction Fields</h3><p>${esc(Array.isArray(a.correctionFields)?a.correctionFields.join(', '):a.correctionFields)}</p></div>`:''}<div class="timeline"><h3>Application Timeline</h3>${timeline(a)}</div>`)}
function field(k,v){return `<div class="field"><span>${esc(k)}</span><b>${esc(v||'—')}</b></div>`}function timeline(a){const st=norm(a.status);const paid=norm(a.paymentStatus)==='paid';return [['Application Submitted',true],['Payment Verified',paid],['Under Process',['under process','approved'].includes(st)],['Approved',st==='approved'],['Rejected',st==='rejected']].map(x=>`<div class="tl ${x[1]?'done':''}"><i class="fa-solid ${x[1]?'fa-check':'fa-circle'}"></i><span>${x[0]}</span></div>`).join('')}
async function setAppStatus(id,status){try{await db.collection('applications').doc(id).update({status,statusUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),statusUpdatedBy:adminUser.email});logAction('Changed application status',`${id} → ${status}`);toast('Status updated');closeModal()}catch(e){toast(e.message,'error')}}
async function verifyPayment(id,ok=true){const a=apps.find(x=>x.id===id);if(!a)return;try{await db.collection('applications').doc(id).update({paymentStatus:ok?'paid':'rejected',paymentVerifiedAt:firebase.firestore.FieldValue.serverTimestamp(),paymentVerifiedBy:adminUser.email});const req=requests.find(r=>r.applicationId===id||r.ackNo===a.ackNo);if(req)await db.collection('customerPaymentRequests').doc(req.id).update({status:ok?'paid':'rejected',paymentStatus:ok?'paid':'rejected',verifiedAt:firebase.firestore.FieldValue.serverTimestamp(),verifiedBy:adminUser.email});logAction(ok?'Verified payment':'Rejected payment',a.ackNo);toast(ok?'Payment verified':'Payment rejected');closeModal()}catch(e){toast(e.message,'error')}}
function viewRequest(id){const r=requests.find(x=>x.id===id);if(!r)return;const app=apps.find(a=>a.id===r.applicationId||a.ackNo===r.ackNo);openModal(`<div class="detail-head"><div><span class="eyebrow">Payment Request</span><h2>${esc(r.name||'Customer')}</h2><p>ACK: <b>${esc(r.ackNo)}</b></p></div>${statusBadge(r.status)}</div><div class="detail-grid">${field('Request ID',r.id)}${field('Amount','₹'+Number(r.amount||190))}${field('Mobile',r.phone)}${field('Application',r.applicationType)}${field('UTR',r.utr||'—')}${field('Created',fmtDate(r.createdAt))}</div><div class="detail-actions"><button class="success" onclick="${app?`verifyPayment('${app.id}',true)`:''}">Verify Payment</button><button class="danger" onclick="${app?`verifyPayment('${app.id}',false)`:''}">Reject Payment</button>${r.paymentScreenshot?`<a class="button" href="${esc(r.paymentScreenshot)}" target="_blank">Payment Proof</a>`:''}</div>`)}
function openDocs(id){const a=apps.find(x=>x.id===id);if(!a)return;const docs=[['Photo',a.photo],['Signature',a.signature],['Aadhaar Front',a.aadhaarFront],['Aadhaar Back',a.aadhaarBack],['DOB Proof',a.dobProof],['Guardian Front',a.guardianFront],['Guardian Back',a.guardianBack]].filter(d=>d[1]);openModal(`<div class="detail-head"><div><span class="eyebrow">Document Center</span><h2>${esc(a.name||'Application')}</h2><p>ACK: ${esc(a.ackNo)} • ${esc(a.applicationType||'PAN')}</p></div></div><div class="doc-grid">${docs.map(d=>`<div class="doc-card"><div class="doc-preview"><img src="${esc(d[1])}" alt="${esc(d[0])}"></div><b>${esc(d[0])}</b><div class="doc-actions"><a href="${esc(d[1])}" target="_blank">Open</a><button onclick="downloadDocJpg('${esc(d[1])}','${esc(a.ackNo+'_'+d[0].replace(/\s+/g,'_'))}')">Download JPG</button></div></div>`).join('')||'<div class="empty">No documents found.</div>'}</div>`)}
function whatsappApp(id){const a=apps.find(x=>x.id===id);if(!a)return;const msg=`TECH SOURCE PAN Update%0AACK: ${a.ackNo}%0AName: ${a.name||''}%0AApplication: ${a.applicationType||'New PAN'}%0AStatus: ${a.status||'pending'}%0APayment: ${a.paymentStatus||'pending'}`;window.open('https://wa.me/'+String(a.phone||'').replace(/\D/g,'')+'?text='+msg,'_blank');logAction('Opened WhatsApp',a.ackNo)}
window.viewApp=viewApp;window.viewRequest=viewRequest;window.verifyPayment=verifyPayment;window.setAppStatus=setAppStatus;window.openDocs=openDocs;window.whatsappApp=whatsappApp;

async function loadActivity(){if(!adminUser)return;try{const s=await db.collection('adminActivity').orderBy('createdAt','desc').limit(100).get();activity=s.docs.map(d=>d.data());$('activityTable').innerHTML=table(['Time','Admin','Action','Detail'],activity.map(x=>`<tr><td>${fmtDate(x.createdAt)}</td><td>${esc(x.adminEmail)}</td><td>${esc(x.action)}</td><td>${esc(x.detail)}</td></tr>`).join(''))}catch(e){$('activityTable').innerHTML='<div class="empty">Activity log unavailable until Firestore rules/index are configured.</div>'}}
function loadSettings(){const raw=localStorage.getItem('ts_pan_admin_settings');if(!raw)return;try{const s=JSON.parse(raw);$('setBusiness').value=s.business||'TECH SOURCE';$('setUpi').value=s.upi||'9661905351-3@axl';$('setFee').value=s.fee||190;$('setWhatsapp').value=s.whatsapp||'9661905351'}catch{}}
$('saveSettings').onclick=()=>{localStorage.setItem('ts_pan_admin_settings',JSON.stringify({business:$('setBusiness').value,upi:$('setUpi').value,fee:$('setFee').value,whatsapp:$('setWhatsapp').value}));$('settingsMsg').textContent='Saved on this admin browser. Firebase application fee remains controlled by the application code.';toast('Settings saved')};
document.querySelectorAll('[data-section]').forEach(btn=>btn.onclick=()=>go(btn.dataset.section));document.querySelectorAll('[data-go]').forEach(btn=>btn.onclick=()=>go(btn.dataset.go));function go(id){document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));$(id).classList.add('active');document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('active',b.dataset.section===id));$('pageTitle').textContent=id==='requests'?'Payment Requests':id==='deleteApplications'?'Delete Applications':id.charAt(0).toUpperCase()+id.slice(1);document.querySelector('.sidebar').classList.remove('open');window.scrollTo(0,0)}$('menuBtn').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');

/* ================= APPROVAL + DOCUMENT CENTER UPGRADE ================= */
async function adminCloudinaryUpload(file, folder='pan_final'){
  const url='https://api.cloudinary.com/v1_1/dsnuatuc8/image/upload'; const fd=new FormData(); fd.append('file',file); fd.append('upload_preset','ml_default'); fd.append('folder',folder);
  const res=await fetch(url,{method:'POST',body:fd}); const d=await res.json(); if(!res.ok||!d.secure_url) throw new Error(d.error?.message||'Cloudinary upload failed'); return d.secure_url.replace('/upload/','/upload/f_auto,q_auto/');
}

function openApproveUpload(id){const a=apps.find(x=>x.id===id);if(!a)return;openModal(`<div class="approval-upload"><div class="detail-head"><div><span class="eyebrow">FINAL PAN CARD</span><h2>Approve: ${esc(a.name||'Application')}</h2><p>ACK: <b>${esc(a.ackNo)}</b></p></div></div><div class="upload-drop"><i class="fa fa-id-card" style="font-size:30px"></i><p>Final PAN card JPG upload karein. Only JPG, JPEG, PNG or WEBP image is allowed.</p><input id="finalPanFile" type="file" accept="image/jpeg,image/png,image/webp"></div><div class="upload-progress"><span id="finalPanProgress"></span></div><p id="finalPanMsg" class="message"></p><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="success" id="finalPanApproveBtn" onclick="uploadFinalPanAndApprove('${id}')">Upload & Approve</button></div></div>`)}
async function uploadFinalPanAndApprove(id){const input=$('finalPanFile'),msg=$('finalPanMsg'),bar=$('finalPanProgress'),btn=$('finalPanApproveBtn');const file=input?.files?.[0];if(!file){msg.textContent='Final PAN card file select karein.';return}btn.disabled=true;msg.textContent='Preparing final PAN…';try{let jpg=file;if(!file.type.startsWith('image/'))throw new Error('Only image files are supported.');bar.style.width='35%';msg.textContent='Uploading final PAN…';const url=await adminCloudinaryUpload(jpg,'pan_final_cards');bar.style.width='85%';await db.collection('applications').doc(id).update({status:'approved',documentUrl:url,panCardUrl:url,finalPanCardUploadedAt:firebase.firestore.FieldValue.serverTimestamp(),statusUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),statusUpdatedBy:adminUser.email});logAction('Approved application + uploaded PAN card',apps.find(x=>x.id===id)?.ackNo||id);bar.style.width='100%';msg.style.color='#15803d';msg.textContent='Approved. PAN card ready for download.';setTimeout(closeModal,700)}catch(e){msg.style.color='#dc2626';msg.textContent=e.message||String(e);btn.disabled=false}}
window.openApproveUpload=openApproveUpload;window.uploadFinalPanAndApprove=uploadFinalPanAndApprove;

async function downloadDocJpg(url,name){try{const r=await fetch(url);const b=await r.blob();if(!b.type.startsWith('image/'))throw new Error('Only image documents can be downloaded.');const img=new Image();img.crossOrigin='anonymous';const u=URL.createObjectURL(b);await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=u});const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;c.getContext('2d').drawImage(img,0,0);const blob=await new Promise(x=>c.toBlob(x,'image/jpeg',.94));URL.revokeObjectURL(u);const out=URL.createObjectURL(blob);const a=document.createElement('a');a.href=out;a.download=name+'.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(out),1000)}catch(e){toast('JPG download failed: '+(e.message||e),'error')}}
window.downloadDocJpg=downloadDocJpg;

