viewRequest=function(id){const r=requests.find(x=>x.id===id);if(!r)return;const app=apps.find(a=>a.id===r.applicationId||a.ackNo===r.ackNo);openModal(`<div class="detail-head"><div><span class="eyebrow">Payment Request</span><h2>${esc(r.name||'Customer')}</h2><p>ACK: <b>${esc(r.ackNo)}</b></p></div>${statusBadge(r.status)}</div><div class="detail-grid">${field('Request ID',r.id)}${field('ACK',r.ackNo)}${field('Amount','₹'+Number(r.amount||190))}${field('Mobile',r.phone)}${field('Application',r.applicationType)}${field('UTR',r.utr||'—')}${field('Status',r.status||'pending')}${field('Created',fmtDate(r.createdAt))}</div><div class="detail-actions">${app?`<button class="success" onclick="verifyPayment('${app.id}',true)">Mark Paid</button><button class="danger" onclick="verifyPayment('${app.id}',false)">Reject Payment</button>`:''}<button onclick="editPaymentRequest('${r.id}')">Edit Request</button>${r.paymentScreenshot?`<button onclick="downloadDocJpg('${esc(r.paymentScreenshot)}','PAYMENT_${esc(r.ackNo)}')">Download Proof JPG</button>`:''}</div>`)};
window.viewRequest=viewRequest;
function editPaymentRequest(id){const r=requests.find(x=>x.id===id);if(!r)return;openModal(`<h2>Edit Payment Request</h2><div class="admin-edit-grid"><div><label>Amount</label><input id="editReqAmount" type="number" min="190" value="${Number(r.amount||190)}"></div><div><label>Status</label><select id="editReqStatus"><option>pending</option><option>customer_marked_paid</option><option>verification_pending</option><option>paid</option><option>rejected</option></select></div><div><label>UTR</label><input id="editReqUtr" value="${esc(r.utr||'')}"></div><div><label>UTR Mode</label><select id="editReqUtrMode"><option value="required">required</option><option value="optional">optional</option></select></div></div><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="success" onclick="savePaymentRequestEdit('${id}')">Save</button></div>`);$('editReqStatus').value=r.status||'pending';$('editReqUtrMode').value=r.utrMode||'required'}
async function savePaymentRequestEdit(id){try{const amount=Math.max(190,Number($('editReqAmount').value||190));const status=$('editReqStatus').value;const utr=$('editReqUtr').value.trim();const mode=$('editReqUtrMode').value;const r=requests.find(x=>x.id===id);await db.collection('customerPaymentRequests').doc(id).update({amount, status,paymentStatus:status,utr,utrMode:mode,utrRequired:mode==='required',adminUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),adminUpdatedBy:adminUser.email});if(r?.applicationId)await db.collection('applications').doc(r.applicationId).update({paymentStatus:status==='paid'?'paid':status,customerPaymentAmount:amount,paymentUtr:utr});toast('Payment request updated');closeModal()}catch(e){toast(e.message,'error')}}
window.editPaymentRequest=editPaymentRequest;window.savePaymentRequestEdit=savePaymentRequestEdit;
