const V3_REMARKS_KEY='ts_pan_remark_presets';
async function loadRemarkPresets(){try{const snap=await db.collection('remarkPresets').orderBy('createdAt','asc').get();return snap.docs.map(d=>({id:d.id,...d.data()}));}catch{return JSON.parse(localStorage.getItem(V3_REMARKS_KEY)||'[]')}}
async function saveRemarkPreset(text){text=String(text||'').trim();if(!text)return;try{await db.collection('remarkPresets').add({text,createdAt:firebase.firestore.FieldValue.serverTimestamp(),createdBy:adminUser.email});}catch{const a=JSON.parse(localStorage.getItem(V3_REMARKS_KEY)||'[]');if(!a.includes(text))a.push(text);localStorage.setItem(V3_REMARKS_KEY,JSON.stringify(a))}}
async function v3OpenRemark(id,status){const a=apps.find(x=>x.id===id);if(!a)return;const presets=await loadRemarkPresets();openModal(`<h2>Update Status & Remark</h2><div class="admin-edit-grid"><div><label>Status<select id="v3RemarkStatus"><option>pending</option><option>under process</option><option>approved</option><option>rejected</option></select></label></div><div><label>Saved Remark<select id="v3RemarkPreset"><option value="">Select saved remark</option>${presets.map(x=>`<option>${esc(x.text)}</option>`).join('')}</select></label></div></div><label>Remark<textarea id="v3RemarkText" rows="4" placeholder="Enter remark…">${esc(a.remark||'')}</textarea></label><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="v3SaveStatusRemark('${id}')">Update Status</button></div>`);$('v3RemarkStatus').value=status||a.status||'pending';$('v3RemarkPreset').onchange=()=>{if($('v3RemarkPreset').value)$('v3RemarkText').value=$('v3RemarkPreset').value};}
async function v3SaveStatusRemark(id){const status=$('v3RemarkStatus').value,remark=$('v3RemarkText').value.trim();try{if(remark)await saveRemarkPreset(remark);await db.collection('applications').doc(id).update({status,remark,statusUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),statusUpdatedBy:adminUser.email});logAction('Updated status and remark',id);toast('Status & remark updated');closeModal();loadAll();}catch(e){toast(e.message,'error')}}
window.v3OpenRemark=v3OpenRemark;window.v3SaveStatusRemark=v3SaveStatusRemark;
// Replace application action modal with a dedicated status+remark workflow.
const _v3ViewAppBase=viewApp;
viewApp=async function(id){const a=apps.find(x=>x.id===id);if(!a)return;openModal(`<div class="detail-head"><div><span class="eyebrow">${esc(a.applicationType||'New PAN')}</span><h2>${esc(a.name||'Application')}</h2><p>ACK: <b>${esc(a.ackNo)}</b> • ${fmtDate(a.createdAt)}</p></div><div>${statusBadge(a.status)} ${statusBadge(a.paymentStatus||'pending')}</div></div><div class="detail-actions"><button class="primary" onclick="v3OpenRemark('${id}','under process')">Update Status / Remark</button><button onclick="openDocs('${id}')">Documents</button><button onclick="whatsappApp('${id}')">WhatsApp</button></div><div class="detail-grid">${field('ACK Number',a.ackNo)}${field('Applicant',a.name)}${field('Mobile',a.phone)}${field('Email',a.email)}${field('PAN',a.panNumber||'—')}${field('DOB',a.dob)}${field('Gender',a.gender)}${field("Father's Name (First • Middle • Last)",[a.fatherFirstName,a.fatherMiddleName,a.fatherlastName||a.fatherLastName].filter(Boolean).join(' ')||a.father||a.fatherName||'—')}${field("Mother's Name (First • Middle • Last)",[a.motherFirstName,a.motherMiddleName,a.motherlastName||a.motherLastName].filter(Boolean).join(' ')||a.mother||a.motherName||'—')}${field('Address',[a.flatNo,a.villageCity,a.postOffice,a.subDivision,a.district,a.state,a.pinCode].filter(Boolean).join(', '))}${field('Payment Amount','₹'+Number(a.paymentAmount||190))}${field('UTR',a.paymentUtr||a.utr||'—')}${field('Remark',a.remark||'—')}</div><div class="timeline"><h3>Application Timeline</h3>${timeline(a)}</div>`)};
window.viewApp=viewApp;



/* ================= APPLICATION EDIT ================= */
function splitPersonName(value, first, middle, last){
  const parts=String(value||'').trim().split(/\s+/).filter(Boolean);
  return {first:parts[0]||'',middle:parts.length>2?parts.slice(1,-1).join(' '):'',last:parts.length>1?parts[parts.length-1]:''};
}
function editApplication(id){
  const a=apps.find(x=>x.id===id); if(!a)return;
  const f=(a.firstName||a.first||''); const m=(a.middleName||a.middle||''); const l=(a.lastName||a.last||'');
  const fp=a.fatherFirstName||'', fm=a.fatherMiddleName||'', fl=a.fatherlastName||a.fatherLastName||'';
  const mp=a.motherFirstName||'', mm=a.motherMiddleName||'', ml=a.motherlastName||a.motherLastName||'';
  const fatherSplit=(fp||fm||fl)?{first:fp,middle:fm,last:fl}:splitPersonName(a.father);
  const motherSplit=(mp||mm||ml)?{first:mp,middle:mm,last:ml}:splitPersonName(a.mother);
  const gp=a.guardianFirstName||'', gm=a.guardianMiddleName||'', gl=a.guardianlastName||a.guardianLastName||'';
  const guardianSplit=(gp||gm||gl)?{first:gp,middle:gm,last:gl}:splitPersonName(a.guardianName);
  const v=x=>esc(x??'');
  openModal(`<div class="application-edit-modal"><div class="detail-head"><div><span class="eyebrow">EDIT APPLICATION</span><h2>${v(a.name||'Application')}</h2><p>ACK: <b>${v(a.ackNo)}</b> • ${v(a.applicationType||'New PAN')}</p></div></div>
  <div class="edit-section"><h3>Applicant Details</h3><div class="admin-edit-grid">
    <label>First Name<input id="eaFirst" value="${v(f)}"></label><label>Middle Name<input id="eaMiddle" value="${v(m)}"></label><label>Last Name<input id="eaLast" value="${v(l)}" required></label>
    <label>Name as per Aadhaar<input id="eaNameAadhar" value="${v(a.nameAadhar||a.nameAsPerAadhaar)}"></label><label>Aadhaar Number<input id="eaAadhaar" value="${v(a.aadhaar||a.aadhar)}"></label><label>Date of Birth<input id="eaDob" type="date" value="${v(a.dob)}"></label>
    <label>Gender<select id="eaGender"><option value="">Select</option><option>Male</option><option>Female</option><option>Other</option></select></label><label>Mobile<input id="eaPhone" value="${v(a.phone)}"></label><label>Email<input id="eaEmail" type="email" value="${v(a.email)}"></label>
  </div></div>
  <div class="edit-section"><h3>Father's Name <small>First → Middle → Last</small></h3><div class="admin-edit-grid"><label>First Name<input id="eaFatherFirst" value="${v(fatherSplit.first)}"></label><label>Middle Name<input id="eaFatherMiddle" value="${v(fatherSplit.middle)}"></label><label>Last Name<input id="eaFatherLast" value="${v(fatherSplit.last)}"></label></div></div>
  <div class="edit-section"><h3>Mother's Name <small>First → Middle → Last</small></h3><div class="admin-edit-grid"><label>First Name<input id="eaMotherFirst" value="${v(motherSplit.first)}"></label><label>Middle Name<input id="eaMotherMiddle" value="${v(motherSplit.middle)}"></label><label>Last Name<input id="eaMotherLast" value="${v(motherSplit.last)}"></label></div></div>
  <div class="edit-section"><h3>Address</h3><div class="admin-edit-grid"><label>Flat No / C/O<input id="eaFlat" value="${v(a.flatNo)}"></label><label>Village / City<input id="eaVillage" value="${v(a.villageCity)}"></label><label>Post Office<input id="eaPost" value="${v(a.postOffice)}"></label><label>Sub Division<input id="eaSub" value="${v(a.subDivision)}"></label><label>District<input id="eaDistrict" value="${v(a.district)}"></label><label>State<input id="eaState" value="${v(a.state)}"></label><label>PIN Code<input id="eaPin" value="${v(a.pinCode)}"></label></div></div>
  <div class="edit-section"><h3>Guardian Details</h3><div class="admin-edit-grid"><label>First Name<input id="eaGuardianFirst" value="${v(guardianSplit.first)}"></label><label>Middle Name<input id="eaGuardianMiddle" value="${v(guardianSplit.middle)}"></label><label>Last Name<input id="eaGuardianLast" value="${v(guardianSplit.last)}"></label></div></div>
  <div class="edit-section"><h3>Correction / Other Details</h3><div class="admin-edit-grid"><label>Old PAN<input id="eaPan" value="${v(a.panNumber||a.oldPan||a.corPAN)}"></label><label>Correction Fields<input id="eaCorrectionFields" value="${v(Array.isArray(a.correctionFields)?a.correctionFields.join(', '):(a.correctionFields||''))}"></label></div><label>Other Correction<textarea id="eaOther">${v(a.otherCorrection||a.otherCorrectionDetails||'')}</textarea></label></div>
  <div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="success" onclick="saveApplicationEdit('${id}')"><i class="fa-solid fa-check"></i> Save Changes</button></div></div>`);
  $('eaGender').value=a.gender||'';
}
async function saveApplicationEdit(id){
  const a=apps.find(x=>x.id===id); if(!a)return;
  const val=id=>document.getElementById(id)?.value?.trim()||'';
  const first=val('eaFirst'), middle=val('eaMiddle'), last=val('eaLast');
  if(!last){toast('Last Name is required','error');return;}
  const father=[val('eaFatherFirst'),val('eaFatherMiddle'),val('eaFatherLast')].filter(Boolean).join(' ');
  const mother=[val('eaMotherFirst'),val('eaMotherMiddle'),val('eaMotherLast')].filter(Boolean).join(' ');
  const guardian=[val('eaGuardianFirst'),val('eaGuardianMiddle'),val('eaGuardianLast')].filter(Boolean).join(' ');
  const correctionRaw=val('eaCorrectionFields');
  const correctionFields=correctionRaw?correctionRaw.split(',').map(x=>x.trim()).filter(Boolean):[];
  const update={firstName:first,middleName:middle,lastName:last,name:[first,middle,last].filter(Boolean).join(' '),nameAadhar:val('eaNameAadhar'),aadhaar:val('eaAadhaar'),dob:val('eaDob'),gender:val('eaGender'),phone:val('eaPhone'),email:val('eaEmail'),father,mother,guardianName:guardian,fatherFirstName:val('eaFatherFirst'),fatherMiddleName:val('eaFatherMiddle'),fatherlastName:val('eaFatherLast'),motherFirstName:val('eaMotherFirst'),motherMiddleName:val('eaMotherMiddle'),motherlastName:val('eaMotherLast'),guardianFirstName:val('eaGuardianFirst'),guardianMiddleName:val('eaGuardianMiddle'),guardianlastName:val('eaGuardianLast'),flatNo:val('eaFlat'),villageCity:val('eaVillage'),postOffice:val('eaPost'),subDivision:val('eaSub'),district:val('eaDistrict'),state:val('eaState'),pinCode:val('eaPin'),panNumber:val('eaPan'),correctionFields,otherCorrection:val('eaOther'),adminEditedAt:firebase.firestore.FieldValue.serverTimestamp(),adminEditedBy:adminUser.email};
  try{await db.collection('applications').doc(id).update(update);logAction('Edited application',a.ackNo);toast('Application updated successfully');closeModal();await loadAll();}catch(e){toast(e.message||'Could not update application','error')}
}
window.editApplication=editApplication;window.saveApplicationEdit=saveApplicationEdit;

/* ================= TECH SOURCE V4 ADMIN WORKFLOW PATCH ================= */
(function(){
  const A$=id=>document.getElementById(id);
  const Aesc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const settingsRef=()=>db.collection('serviceSettings').doc('pan');
  const workflow=[
    ['payment_verification','Payment Verification'],['document_verification','Document Verification'],['under_process','Under Process'],['pan_processing','PAN Processing'],['approved','Approved'],['final_upload','Final PAN Upload'],['completed','Completed']
  ];
  const label={photo:'Photo',signature:'Signature',aadhaarFront:'Aadhaar Front',aadhaarBack:'Aadhaar Back',dobProof:'DOB Proof',guardianFront:'Guardian Aadhaar Front',guardianBack:'Guardian Aadhaar Back',oldPanCopy:'Old PAN Card Copy'};
  const norm2=v=>String(v||'').toLowerCase();
  const stage=(a)=>a.workflowStage||((String(a.paymentStatus||'').toLowerCase()==='paid')?'document_verification':'payment_verification');
  const countBadge=(id,n)=>{const e=A$(id);if(!e)return;e.textContent=n;e.hidden=!n;};

  async function loadV4Settings(){try{const s=await settingsRef().get();const d=s.exists?s.data():{};A$('setBusiness').value=d.businessName||'TECH SOURCE';A$('setUpi').value=d.upiId||'9661905351-3@axl';A$('setFee').value=Number(d.panFee||190);A$('setWhatsapp').value=d.whatsapp||'9661905351';}catch(e){}}
  async function saveV4Settings(){const data={businessName:A$('setBusiness').value.trim()||'TECH SOURCE',upiId:A$('setUpi').value.trim(),panFee:Math.max(1,Number(A$('setFee').value||190)),whatsapp:A$('setWhatsapp').value.trim(),updatedAt:firebase.firestore.FieldValue.serverTimestamp(),updatedBy:adminUser?.email||''};try{await settingsRef().set(data,{merge:true});A$('settingsMsg').textContent='Settings saved to Firebase for all users.';toast('Settings saved');loadV4Remarks();}catch(e){A$('settingsMsg').textContent='Save failed: '+e.message;toast(e.message,'error')}}
  A$('saveSettings').onclick=saveV4Settings;

  async function loadV4Remarks(){const box=A$('remarkPresetList');if(!box)return;try{const s=await db.collection('remarkPresets').orderBy('createdAt','asc').get();const arr=s.docs.map(d=>({id:d.id,...d.data()}));box.innerHTML=arr.map(r=>`<div class="remark-row"><span>${Aesc(r.text)}</span><div class="remark-row-actions"><button type="button" class="mini" onclick="editV4Remark('${r.id}','${Aesc(r.text)}')"><i class="fa fa-pen"></i></button><button type="button" class="mini danger" onclick="deleteV4Remark('${r.id}')"><i class="fa fa-trash"></i></button></div></div>`).join('')||'<div class="empty">No saved remarks.</div>';}catch(e){box.innerHTML='<div class="empty">Remarks unavailable until Firestore rules/index are configured.</div>';}}
  async function addV4Remark(){const input=A$('newRemarkText'),text=input.value.trim();if(!text)return;try{await db.collection('remarkPresets').add({text,createdAt:firebase.firestore.FieldValue.serverTimestamp(),createdBy:adminUser.email});input.value='';toast('Remark added');loadV4Remarks();}catch(e){toast(e.message,'error')}}
  window.deleteV4Remark=async id=>{try{await db.collection('remarkPresets').doc(id).delete();toast('Remark deleted');loadV4Remarks();}catch(e){toast(e.message,'error')}};
window.editV4Remark=async function(id,text){
  const next=prompt('Edit saved remark:',text||'');
  if(next===null)return;
  const value=next.trim(); if(!value){toast('Remark cannot be empty.','error');return;}
  try{await db.collection('remarkPresets').doc(id).update({text:value,updatedAt:firebase.firestore.FieldValue.serverTimestamp(),updatedBy:adminUser?.email||''});toast('Remark updated');loadV4Remarks();}
  catch(e){toast(e.message,'error')}
};
  A$('addRemarkBtn')?.addEventListener('click',addV4Remark);

  function v4RenderBadges(){
    const pendingApps=apps.filter(a=>!['completed','approved'].includes(norm2(stage(a))) && norm2(a.status)!=='rejected').length;
    const payment=apps.filter(a=>String(a.paymentStatus||'').toLowerCase()==='verification_pending').length+requests.filter(r=>['customer_marked_paid','verification_pending'].includes(norm2(r.status))).length;
    const docs=apps.filter(a=>stage(a)==='document_verification'||(Array.isArray(a.rejectedDocuments)&&a.rejectedDocuments.length)).length;
    const req=requests.filter(r=>['pending','customer_marked_paid','verification_pending'].includes(norm2(r.status))).length;
    countBadge('badgeApplications',pendingApps);countBadge('badgePayments',payment);countBadge('badgeDocuments',docs);countBadge('badgeRequests',req);
  }
  const _renderAll=window.renderAll;window.renderAll=function(){_renderAll();v4RenderBadges();v4RenderDeleteList();};

  // Application status + remark workflow. Approval cannot be skipped and final upload is required.
  async function openV4StatusModal(id){const a=apps.find(x=>x.id===id);if(!a)return;const current=stage(a);const currentIdx=Math.max(0,workflow.findIndex(x=>x[0]===current));let remarks=[];try{const s=await db.collection('remarkPresets').orderBy('createdAt','asc').get();remarks=s.docs.map(d=>d.data().text);}catch(e){}
    const options=workflow.map((x,i)=>`<option value="${x[0]}" ${i<currentIdx?'disabled':''}>${x[1]}</option>`).join('');
    openModal(`<div class="v4-status-modal"><span class="eyebrow">WORKFLOW UPDATE</span><h2>${Aesc(a.name||'Application')}</h2><p>ACK: <b>${Aesc(a.ackNo)}</b></p><div class="workflow-current"><span>Current</span><strong>${Aesc(workflow.find(x=>x[0]===current)?.[1]||current)}</strong></div><label>Status / Stage<select id="v4StageSelect">${options}</select></label><label>Saved Remark<select id="v4RemarkSelect"><option value="">Select remark</option>${remarks.map(r=>`<option>${Aesc(r)}</option>`).join('')}</select></label><label>Remark<textarea id="v4RemarkText" rows="3" placeholder="Remark for customer…">${Aesc(a.remark||'')}</textarea></div><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="v4SaveStage('${id}')">Save Update</button></div>`);
    A$('v4StageSelect').value=current;A$('v4RemarkSelect').onchange=()=>{if(A$('v4RemarkSelect').value)A$('v4RemarkText').value=A$('v4RemarkSelect').value;};
  }
  async function v4SaveStage(id){const a=apps.find(x=>x.id===id);if(!a)return;const next=A$('v4StageSelect').value,remark=A$('v4RemarkText').value.trim(),cur=stage(a),ci=workflow.findIndex(x=>x[0]===cur),ni=workflow.findIndex(x=>x[0]===next);if(ni<ci){toast('Previous workflow stage cannot be selected.','error');return;}if(next==='payment_verification'){toast('Payment verification is the first stage.','error');return;}if(next!=='payment_verification'&&String(a.paymentStatus||'').toLowerCase()!=='paid'){toast('Payment must be verified before documents/process.','error');return;}if(['under_process','pan_processing','approved','final_upload','completed'].includes(next)&&!v4AllDocsVerified(a)){toast('All required documents must be verified first.','error');return;}try{const update={workflowStage:next,remark,status:next==='completed'?'completed':next==='approved'?'approved':next==='rejected'?'rejected':'under process',statusUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),statusUpdatedBy:adminUser.email};if(remark){update.remark=remark;await db.collection('remarkPresets').add({text:remark,createdAt:firebase.firestore.FieldValue.serverTimestamp(),createdBy:adminUser.email}).catch(()=>{});}await db.collection('applications').doc(id).update(update);logAction('Updated workflow stage',`${a.ackNo} → ${next}${remark?' | '+remark:''}`);toast('Workflow updated');closeModal();renderAll();}catch(e){toast(e.message,'error')}}
  function v4AllDocsVerified(a){const docs=v4DocList(a);return docs.length>0&&docs.every(d=>norm2((a.documentStatuses||{})[d.key]||'pending')==='verified');}
  window.v4OpenStatusModal=openV4StatusModal;window.v4SaveStage=v4SaveStage;

  // Payment verification moves the application to document verification only.
  window.verifyPayment=async function(id,ok=true){const a=apps.find(x=>x.id===id);if(!a)return;try{const now=firebase.firestore.FieldValue.serverTimestamp();const update={paymentStatus:ok?'paid':'rejected',paymentVerifiedAt:now,paymentVerifiedBy:adminUser.email,paymentRemark:A$('v4PaymentRemarkText')?.value?.trim()||''};if(ok)update.workflowStage='document_verification';await db.collection('applications').doc(id).update(update);const req=requests.find(r=>r.applicationId===id||r.ackNo===a.ackNo);if(req)await db.collection('customerPaymentRequests').doc(req.id).update({status:ok?'paid':'rejected',paymentStatus:ok?'paid':'rejected',verifiedAt:now,verifiedBy:adminUser.email,remark:update.paymentRemark});logAction(ok?'Verified payment':'Rejected payment',a.ackNo);toast(ok?'Payment verified → Document Verification':'Payment rejected');closeModal();renderAll();}catch(e){toast(e.message,'error')}};

  // Documents with per-document verification/rejection and direct re-upload route.
  function v4DocList(a){const docs=[['photo',a.photo],['signature',a.signature],['aadhaarFront',a.aadhaarFront],['aadhaarBack',a.aadhaarBack],['dobProof',a.dobProof],['guardianFront',a.guardianFront],['guardianBack',a.guardianBack],['oldPanCopy',a.oldPanCopy]].filter(x=>x[1]||((a.rejectedDocuments||[]).some(r=>r.key===x[0])));return docs.map(([key,url])=>({key,url,label:label[key]}));}
  function v4DocCard(a,d){const st=(a.documentStatuses||{})[d.key]||((a.rejectedDocuments||[]).some(x=>x.key===d.key)?'rejected':'pending');const rej=(a.rejectedDocuments||[]).find(x=>x.key===d.key);return `<div class="doc-card v4-doc-card ${st}"><div class="doc-preview">${d.url?`<img src="${Aesc(d.url)}" alt="${Aesc(d.label)}">`:'<div class="doc-missing">No image</div>'}</div><div class="v4-doc-title"><b>${Aesc(d.label)}</b>${statusBadge(st)}</div>${rej?`<div class="doc-reason">${Aesc(rej.remark||'Rejected')}</div>`:''}<div class="doc-actions"><button type="button" onclick="v4ViewImage('${Aesc(d.url||'')}','${Aesc(d.label)}')">View</button>${d.url?`<button type="button" onclick="v4DownloadImage('${Aesc(d.url)}','${Aesc(a.ackNo+'_'+d.label.replace(/\s+/g,'_'))}')">Download</button>`:''}${st!=='verified'?`<button class="success" type="button" onclick="v4VerifyDoc('${a.id}','${d.key}')">Verify</button>`:''}<button class="danger" type="button" onclick="v4RejectDoc('${a.id}','${d.key}')">Reject</button>${st==='rejected'?`<button type="button" onclick="v4OpenAdminDocUpload('${a.id}','${d.key}')">Upload</button>`:''}</div></div>`}
  window.openDocs=function(id){const a=apps.find(x=>x.id===id);if(!a)return;openModal(`<div class="detail-head"><div><span class="eyebrow">DOCUMENT CENTER</span><h2>${Aesc(a.name||'Application')}</h2><p>ACK: ${Aesc(a.ackNo)}</p></div></div><div class="v4-doc-help">Verify each document separately. Rejecting one document lets the customer replace only that document.</div><div class="doc-grid">${v4DocList(a).map(d=>v4DocCard(a,d)).join('')||'<div class="empty">No documents found.</div>'}</div>`)};
  window.v4VerifyDoc=async function(id,key){const a=apps.find(x=>x.id===id);if(!a)return;if(String(a.paymentStatus||'').toLowerCase()!=='paid'){toast('Payment must be verified before document verification.','error');return;}try{const statuses={...(a.documentStatuses||{}),[key]:'verified'};const rejected=(a.rejectedDocuments||[]).filter(x=>x.key!==key);const update={documentStatuses:statuses,rejectedDocuments:rejected,documentUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),documentUpdatedBy:adminUser.email};const docs=v4DocList({...a,documentStatuses:statuses,rejectedDocuments:rejected});if(String(a.paymentStatus||'').toLowerCase()==='paid'&&docs.length&&docs.every(d=>statuses[d.key]==='verified'))update.workflowStage='under_process';await db.collection('applications').doc(id).update(update);logAction('Verified document',`${a.ackNo} | ${key}`);toast(`${label[key]} verified`);openDocs(id);}catch(e){toast(e.message,'error')}};
  window.v4RejectDoc=async function(id,key){const a=apps.find(x=>x.id===id);if(!a)return;const presets=[];try{const s=await db.collection('remarkPresets').orderBy('createdAt','asc').get();s.forEach(d=>presets.push(d.data().text));}catch(e){}openModal(`<h2>Reject ${Aesc(label[key])}</h2><label>Saved Remark<select id="v4DocRemark"><option value="">Select reason</option>${presets.map(r=>`<option>${Aesc(r)}</option>`).join('')}</select></label><label>Remark<textarea id="v4DocRemarkText" rows="3" placeholder="Why is this document rejected?"></textarea></label><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="danger" onclick="v4SaveDocReject('${id}','${key}')">Reject Document</button></div>`);A$('v4DocRemark').onchange=()=>{if(A$('v4DocRemark').value)A$('v4DocRemarkText').value=A$('v4DocRemark').value;};};
  window.v4SaveDocReject=async function(id,key){const a=apps.find(x=>x.id===id),remark=A$('v4DocRemarkText').value.trim()||'Document rejected. Please upload a clearer/correct document.';try{const rej=[...(a.rejectedDocuments||[]).filter(x=>x.key!==key),{key,label:label[key],remark,rejectedAt:new Date().toISOString(),rejectedBy:adminUser.email}];const statuses={...(a.documentStatuses||{}),[key]:'rejected'};await db.collection('applications').doc(id).update({documentStatuses:statuses,rejectedDocuments:rej,workflowStage:'document_verification',remark,status:'pending',statusUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),statusUpdatedBy:adminUser.email});await db.collection('remarkPresets').add({text:remark,createdAt:firebase.firestore.FieldValue.serverTimestamp(),createdBy:adminUser.email}).catch(()=>{});logAction('Rejected document',`${a.ackNo} | ${key} | ${remark}`);toast('Document rejected — customer can re-upload only this document');closeModal();renderAll();}catch(e){toast(e.message,'error')}};
  window.v4ViewImage=function(url,title){if(!url)return;openModal(`<div class="v4-image-viewer"><span class="eyebrow">${Aesc(title)}</span><img src="${Aesc(url)}" alt="${Aesc(title)}"><div class="detail-actions"><button onclick="closeModal()">Close</button><button class="primary" onclick="v4DownloadImage('${Aesc(url)}','${Aesc(title.replace(/\s+/g,'_'))}')">Download</button></div></div>`)};
  window.v4DownloadImage=async function(url,name){try{const r=await fetch(url);const b=await r.blob();if(!b.type.startsWith('image/'))throw new Error('Only image downloads are allowed.');const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download=(name||'document')+'.jpg';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}catch(e){toast('Image download failed: '+e.message,'error')}};
  window.v4OpenAdminDocUpload=function(id,key){const a=apps.find(x=>x.id===id);if(!a)return;openModal(`<h2>Replace ${Aesc(label[key])}</h2><p>ACK: <b>${Aesc(a.ackNo)}</b></p><input id="v4AdminDocFile" type="file" accept="image/jpeg,image/png,image/webp"><p id="v4AdminDocMsg" class="message"></p><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="v4AdminUploadDoc('${id}','${key}')">Upload</button></div>`)};
  window.v4AdminUploadDoc=async function(id,key){const f=A$('v4AdminDocFile')?.files?.[0];if(!f||!f.type.startsWith('image/')){A$('v4AdminDocMsg').textContent='Select an image file.';return;}try{A$('v4AdminDocMsg').textContent='Uploading…';const url=await adminCloudinaryUpload(f,'pan_applications');const a=apps.find(x=>x.id===id);const rej=(a.rejectedDocuments||[]).filter(x=>x.key!==key);const statuses={...(a.documentStatuses||{}),[key]:'pending'};await db.collection('applications').doc(id).update({[key]:url,rejectedDocuments:rej,documentStatuses:statuses,workflowStage:'document_verification'});toast('Replacement uploaded');openDocs(id);}catch(e){A$('v4AdminDocMsg').textContent=e.message||String(e);}};

  // Final PAN upload is image-only and occurs after Approved stage; upload changes stage to completed.
  window.openApproveUpload=function(id){const a=apps.find(x=>x.id===id);if(!a)return;if(String(a.paymentStatus||'').toLowerCase()!=='paid'||!v4AllDocsVerified(a)){toast('Payment and all documents must be verified before final upload.','error');return;}openModal(`<div class="approval-upload"><span class="eyebrow">FINAL PAN CARD</span><h2>Upload Final PAN — ${Aesc(a.name||'')}</h2><p>ACK: <b>${Aesc(a.ackNo)}</b></p><input id="finalPanFile" type="file" accept="image/jpeg,image/png,image/webp"><p id="finalPanMsg" class="message"></p><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="success" onclick="uploadFinalPanAndApprove('${id}')">Upload Final PAN</button></div></div>`)};
  window.uploadFinalPanAndApprove=async function(id){const f=A$('finalPanFile')?.files?.[0];if(!f||!f.type.startsWith('image/')){A$('finalPanMsg').textContent='Only JPG, JPEG, PNG or WEBP final PAN image is allowed.';return;}try{A$('finalPanMsg').textContent='Uploading…';const url=await adminCloudinaryUpload(f,'pan_final_cards');const now=firebase.firestore.FieldValue.serverTimestamp();await db.collection('applications').doc(id).update({workflowStage:'completed',status:'completed',documentUrl:url,panCardUrl:url,finalPanCardUploadedAt:now,statusUpdatedAt:now,statusUpdatedBy:adminUser.email});logAction('Final PAN uploaded — completed',apps.find(x=>x.id===id)?.ackNo||id);toast('Final PAN uploaded. Application completed.');closeModal();renderAll();}catch(e){A$('finalPanMsg').textContent=e.message||String(e)}};

  // Override application view with workflow controls.
  window.viewApp=function(id){const a=apps.find(x=>x.id===id);if(!a)return;const st=stage(a);const docs=v4DocList(a);openModal(`<div class="detail-head"><div><span class="eyebrow">${Aesc(a.applicationType||'New PAN')}</span><h2>${Aesc(a.name||'Application')}</h2><p>ACK: <b>${Aesc(a.ackNo)}</b> • ${fmtDate(a.createdAt)}</p></div><div>${statusBadge(st)} ${statusBadge(a.paymentStatus||'pending')}</div></div><div class="workflow-strip">${workflow.map((x,i)=>`<div class="wf-step ${i<=workflow.findIndex(y=>y[0]===st)?'done':''}"><span>${i+1}</span><small>${Aesc(x[1])}</small></div>`).join('')}</div><div class="detail-actions">${String(a.paymentStatus||'').toLowerCase()==='verification_pending'?`<button class="success" onclick="verifyPayment('${id}',true)">Verify Payment</button><button class="danger" onclick="verifyPayment('${id}',false)">Reject Payment</button>`:''}<button class="primary" onclick="v4OpenStatusModal('${id}')">Status / Remark</button><button class="primary" onclick="editApplication('${id}')"><i class="fa-solid fa-pen"></i> Edit</button><button onclick="openDocs('${id}')">Documents</button><button onclick="whatsappApp('${id}')">WhatsApp</button>${st==='approved'?`<button class="success" onclick="openApproveUpload('${id}')">Final PAN Upload</button>`:''}</div><div class="detail-grid">${field('ACK Number',a.ackNo)}${field('Applicant',a.name)}${field('Mobile',a.phone)}${field('Email',a.email)}${field('PAN',a.panNumber||'—')}${field('DOB',a.dob)}${field('Gender',a.gender)}${field("Father's Name (First • Middle • Last)",[a.fatherFirstName,a.fatherMiddleName,a.fatherlastName||a.fatherLastName].filter(Boolean).join(' ')||a.father||a.fatherName||'—')}${field("Mother's Name (First • Middle • Last)",[a.motherFirstName,a.motherMiddleName,a.motherlastName||a.motherLastName].filter(Boolean).join(' ')||a.mother||a.motherName||'—')}${field('Address',[a.flatNo,a.villageCity,a.postOffice,a.subDivision,a.district,a.state,a.pinCode].filter(Boolean).join(', '))}${field('Payment Amount','₹'+Number(a.paymentAmount||a.customerPaymentAmount||190))}${field('UTR',a.paymentUtr||a.utr||'—')}${field('Remark',a.remark||'—')}</div><div class="subpanel"><h3>Documents</h3><p>${docs.filter(d=>(a.documentStatuses||{})[d.key]==='verified').length}/${docs.length} verified</p></div>`)};

  // Delete Applications: ACK confirmation + complete Firestore cleanup for linked records.
  async function v4DeleteCandidates(){const q=norm2(A$('deleteSearch')?.value);const list=apps.filter(a=>!q||[a.ackNo,a.name,a.phone,a.email,a.panNumber].some(v=>norm2(v).includes(q)));const box=A$('deleteApplicationsTable');if(!box)return;box.innerHTML=list.map(a=>`<article class="delete-app-card"><img src="${Aesc(a.photo||'https://ui-avatars.com/api/?name=TS&background=dc2626&color=fff')}" alt=""><div><b>${Aesc(a.name||'Application')}</b><span>ACK: ${Aesc(a.ackNo||'—')}</span><span>${Aesc(a.applicationType||'New PAN')} • ${Aesc(stage(a))}</span></div><button class="danger" onclick="v4ConfirmDelete('${a.id}')"><i class="fa fa-trash-can"></i> Delete</button></article>`).join('')||'<div class="empty">No applications found.</div>'}
  window.v4ConfirmDelete=function(id){const a=apps.find(x=>x.id===id);if(!a)return;openModal(`<div class="delete-confirm-modal"><div class="delete-icon"><i class="fa fa-trash-can"></i></div><span class="eyebrow">PERMANENT DELETE</span><h2>Delete Application?</h2><div class="delete-identity"><img src="${Aesc(a.photo||'https://ui-avatars.com/api/?name=TS&background=dc2626&color=fff')}" alt=""><div><b>${Aesc(a.name||'—')}</b><span>ACK: ${Aesc(a.ackNo||'—')}</span></div></div><p>This will permanently delete this application's Firestore records, payment-link/request records and related application activity.</p><label>Enter exact ACK: <input id="v4DeleteAck" autocomplete="off" placeholder="${Aesc(a.ackNo||'')}"></label><p id="v4DeleteMsg" class="delete-error"></p><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="danger" onclick="v4DeleteApplication('${id}')">Delete Permanently</button></div></div>`)};
  window.v4DeleteApplication=async function(id){const a=apps.find(x=>x.id===id),input=A$('v4DeleteAck'),msg=A$('v4DeleteMsg');if(!a)return;if(input.value.trim().toUpperCase()!==(a.ackNo||'').toUpperCase()){msg.textContent='Wrong ACK. Please enter the exact ACK shown above.';return;}try{const targets=[db.collection('applications').doc(id)];const req1=await db.collection('customerPaymentRequests').where('applicationId','==',id).get();req1.forEach(d=>targets.push(d.ref));const req2=await db.collection('customerPaymentRequests').where('ackNo','==',a.ackNo).get();req2.forEach(d=>targets.push(d.ref));const acts=await db.collection('adminActivity').limit(1000).get();acts.forEach(d=>{const x=d.data()||{};if(String(x.detail||'').includes(String(a.ackNo||'')))targets.push(d.ref);});const unique=[...new Map(targets.map(r=>[r.path,r])).values()];for(let i=0;i<unique.length;i+=450){const batch=db.batch();unique.slice(i,i+450).forEach(ref=>batch.delete(ref));await batch.commit();}logAction('Deleted application',a.ackNo);toast('Application and related Firestore records deleted');closeModal();renderAll();}catch(e){msg.textContent='Delete failed: '+(e.message||e)}};
  function v4RenderDeleteList(){if(A$('deleteApplications'))v4DeleteCandidates();}
  A$('deleteSearch')?.addEventListener('input',v4RenderDeleteList);

  // Search docs section should use the same secure document viewer.

  // Initialize.
  setTimeout(()=>{loadV4Settings();loadV4Remarks();v4RenderBadges();v4RenderDeleteList();},250);
})();
/* V4 admin payment retry routing + rejected-link recovery */
(function(){
  window.v4OpenPaymentRetryFromAdmin=async function(id){const a=apps.find(x=>x.id===id);if(!a)return;try{const r=requests.find(x=>x.applicationId===id||x.ackNo===a.ackNo);if(r){window.open((window.location.origin+window.location.pathname)+'?customerPayId='+encodeURIComponent(r.id),'_blank');}else{window.open((window.location.origin+window.location.pathname)+'?customerPay='+encodeURIComponent(a.ackNo),'_blank');}}catch(e){toast(e.message||String(e),'error')}};
  const oldView=window.viewApp;
  // Patch only the action button by wrapping the current rendered modal content.
  const baseView=oldView;
  window.viewApp=function(id){baseView(id);setTimeout(()=>{const a=apps.find(x=>x.id===id);if(!a||String(a.paymentStatus||'').toLowerCase()!=='rejected')return;const box=document.querySelector('#modalBody .detail-actions');if(!box)return;const b=document.createElement('button');b.className='primary';b.textContent='Open Payment Page';b.onclick=()=>v4OpenPaymentRetryFromAdmin(id);box.appendChild(b);},0)};
})();

/* TECH SOURCE FINAL ADMIN PATCH */
(function(){
  const escF=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const labelsF={photo:'Photo',signature:'Signature',aadhaarFront:'Aadhaar Front',aadhaarBack:'Aadhaar Back',dobProof:'DOB Proof',guardianFront:'Guardian Aadhaar Front',guardianBack:'Guardian Aadhaar Back',oldPanCopy:'Old PAN Card Copy'};
  const workflowF=[['payment_verification','Payment Verification'],['document_verification','Document Verification'],['under_process','Under Process'],['pan_processing','PAN Processing'],['approved','Approved'],['final_upload','Final PAN Upload'],['completed','Completed']];
  function docKeysF(a){
    const keys=['photo','signature','aadhaarFront','aadhaarBack','dobProof'];
    if(a.guardianFront)keys.push('guardianFront');
    if(a.guardianBack)keys.push('guardianBack');
    if(a.oldPanCopy)keys.push('oldPanCopy');
    return keys;
  }
  function isFullyVerifiedF(a){const keys=docKeysF(a),s=a.documentStatuses||{};return keys.length>0&&keys.every(k=>String(s[k]||'pending').toLowerCase()==='verified');}
  function refreshDocSelectorF(){
    const sel=$('docApplicationSelect'); if(!sel)return;
    const keep=sel.value;
    const eligible=apps.filter(a=>!isFullyVerifiedF(a));
    sel.innerHTML='<option value="">Select application</option>'+eligible.map(a=>`<option value="${escF(a.id)}">${escF(a.ackNo||'No ACK')} — ${escF(a.name||'Application')}</option>`).join('');
    if(eligible.some(a=>a.id===keep))sel.value=keep;
    if(!keep && eligible.length===1)sel.value=eligible[0].id;
  }
  function renderSelectedDocsF(id){
    const box=$('documentResult'); if(!box)return;
    if(!id){box.classList.add('empty');box.innerHTML='Select an application to view documents.';return;}
    const a=apps.find(x=>x.id===id); if(!a){box.classList.add('empty');box.innerHTML='Application not found.';return;}
    box.classList.remove('empty');
    // Use the existing secure document viewer so View/Download/Verify/Reject/Upload actions stay identical.
    if(window.openDocs){window.openDocs(a.id);return;}
  }
  $('docApplicationSelect')?.addEventListener('change',e=>renderSelectedDocsF(e.target.value));
  const oldRenderAllF=window.renderAll;
  window.renderAll=function(){oldRenderAllF?.();refreshDocSelectorF();};
  // Strict next-stage enforcement: no stage skipping and final completion only after final PAN upload.
  window.v4OpenStatusModal=async function(id){
    const a=apps.find(x=>x.id===id); if(!a)return;
    const current=String(a.workflowStage||((String(a.paymentStatus||'').toLowerCase()==='paid')?'document_verification':'payment_verification')).toLowerCase();
    const idx=workflowF.findIndex(x=>x[0]===current);
    const next=workflowF[idx+1];
    let remarks=[];
    try{const s=await db.collection('remarkPresets').orderBy('createdAt','asc').get();remarks=s.docs.map(d=>String(d.data().text||'')).filter(Boolean);}catch(e){}
    const isManual=next && ['under_process','pan_processing','approved'].includes(next[0]);
    if(!next){toast('Application is already at the final stage.','error');return;}
    let html=`<div class="v4-status-modal"><span class="eyebrow">NEXT WORKFLOW STEP</span><h2>${escF(a.name||'Application')}</h2><p>ACK: <b>${escF(a.ackNo)}</b></p><div class="workflow-current"><span>Current</span><strong>${escF(workflowF[idx]?.[1]||current)}</strong></div><div class="next-stage-note">Next allowed stage: <b>${escF(next[1])}</b></div>`;
    if(isManual){html+=`<label>Remark<select id="v4RemarkSelect"><option value="">Select saved remark</option>${remarks.map(r=>`<option value="${escF(r)}">${escF(r)}</option>`).join('')}</select></label><label>Customer Remark<textarea id="v4RemarkText" rows="3" placeholder="Optional remark for customer…">${escF(a.remark||'')}</textarea></label>`;}
    html+=`<div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="v4SaveStage('${escF(id)}')">Move to ${escF(next[1])}</button></div></div>`;
    openModal(html);
    $('v4RemarkSelect')?.addEventListener('change',e=>{if(e.target.value)$('v4RemarkText').value=e.target.value;});
  };
  window.v4SaveStage=async function(id){
    const a=apps.find(x=>x.id===id);if(!a)return;
    const cur=String(a.workflowStage||((String(a.paymentStatus||'').toLowerCase()==='paid')?'document_verification':'payment_verification')).toLowerCase();
    const ci=workflowF.findIndex(x=>x[0]===cur), next=workflowF[ci+1];
    if(!next){toast('No further workflow step is available.','error');return;}
    if(next[0]==='document_verification'){toast('Payment verification must be completed first.','error');return;}
    if(String(a.paymentStatus||'').toLowerCase()!=='paid'){toast('Payment must be verified before continuing.','error');return;}
    if(next[0]==='under_process'&&!docKeysF(a).every(k=>String((a.documentStatuses||{})[k]||'pending').toLowerCase()==='verified')){toast('All required documents must be verified first.','error');return;}
    if(next[0]==='completed'){toast('Completed is set automatically after final PAN upload.','error');return;}
    const remark=$('v4RemarkText')?.value?.trim()||'';
    try{
      const update={workflowStage:next[0],status:next[0]==='approved'?'approved':'under process',statusUpdatedAt:firebase.firestore.FieldValue.serverTimestamp(),statusUpdatedBy:adminUser.email};
      if(remark)update.remark=remark;
      await db.collection('applications').doc(id).update(update);
      logAction('Moved workflow stage',`${a.ackNo} → ${next[0]}${remark?' | '+remark:''}`);
      toast(`Moved to ${next[1]}`);closeModal();renderAll();
    }catch(e){toast(e.message||String(e),'error');}
  };
  // Payment verification always starts document verification; payment rejection remains retryable.
  window.verifyPayment=async function(id,ok=true){
    const a=apps.find(x=>x.id===id);if(!a)return;
    const save=async remark=>{
      try{
        const now=firebase.firestore.FieldValue.serverTimestamp();
        const update={paymentStatus:ok?'paid':'rejected',paymentVerifiedAt:now,paymentVerifiedBy:adminUser.email,paymentRemark:remark||''};
        if(ok)update.workflowStage='document_verification';
        await db.collection('applications').doc(id).update(update);
        const req=requests.find(r=>r.applicationId===id||r.ackNo===a.ackNo);
        if(req)await db.collection('customerPaymentRequests').doc(req.id).update({status:ok?'paid':'rejected',paymentStatus:ok?'paid':'rejected',verifiedAt:now,verifiedBy:adminUser.email,remark:remark||''});
        logAction(ok?'Verified payment':'Rejected payment',`${a.ackNo}${remark?' | '+remark:''}`);toast(ok?'Payment verified → Document Verification':'Payment rejected');closeModal();renderAll();
      }catch(e){toast(e.message||String(e),'error');}
    };
    if(ok){await save('');return;}
    let remarks=[];try{const s=await db.collection('remarkPresets').orderBy('createdAt','asc').get();remarks=s.docs.map(d=>String(d.data().text||'')).filter(Boolean);}catch(e){}
    openModal(`<div class="v4-status-modal"><span class="eyebrow">PAYMENT REJECTION</span><h2>${escF(a.name||'Customer')}</h2><p>ACK: <b>${escF(a.ackNo)}</b></p><label>Saved Remark<select id="v4PayRemarkSelect"><option value="">Select remark</option>${remarks.map(r=>`<option value="${escF(r)}">${escF(r)}</option>`).join('')}</select></label><label>Remark<textarea id="v4PayRemarkText" rows="3" placeholder="Payment rejection reason…"></textarea></label><div class="detail-actions"><button onclick="closeModal()">Cancel</button><button class="danger" id="v4PayRejectConfirm">Reject Payment</button></div></div>`);
    $('v4PayRemarkSelect').onchange=()=>{if($('v4PayRemarkSelect').value)$('v4PayRemarkText').value=$('v4PayRemarkSelect').value;};
    $('v4PayRejectConfirm').onclick=()=>save($('v4PayRemarkText').value.trim());
  };
  // Ensure the selector is ready immediately and after live snapshots.
  setTimeout(refreshDocSelectorF,300);
})();
